function Honghu.jaff_rhs!(du, ::Network, nden, photden, rflux, tgas, c_hat)
    # $$JAFF REPEAT idx, rhs, cse IN rhses { USE honghu }
    cse0 = c_hat .* nden[0+1] .* photden[0+1]
    cse1 = 1.63000002608529e-18 * cse0
    cse2 = sqrt(tgas)
    cse3 = 1 ./ tgas
    cse4 = nden[0+1] .* nden[2+1]
    cse5 = cse2 .* cse4 .* exp(-157896.75724967 * cse3)
    cse6 = cse1 + 5.84e-11 * cse5 - 1.65941781598291e-10 * tgas .^ (-0.7) .* nden[1+1] .* nden[2+1]
    du[1] = -cse6
    du[2] = cse6
    du[3] = cse6
    du[4] = 4.19153446811725e-29 * cse0 - 7.5e-19 * cse4 .* exp(-118348.0 * cse3) ./ (0.00316227766016838 * cse2 + 1) - 1.27251276978816e-21 * cse5 + (-1.8551e-27 * cse2 - ((tgas < 100.0) ? (0.0) : (8.4219589e-26 * tgas .^ 0.11))) .* nden[1+1] .* nden[2+1]
    du[5] = -cse1
    du[6] = -1.63000002608529e-18 * c_hat .* nden[0+1] .* rflux[0+1]
    # $$JAFF END
    return nothing
end

function Honghu.jaff_jacobian!(J, ::Network, nden, photden, rflux, tgas, c_hat)
    # $$JAFF REPEAT idx, expr, cse IN jacobian { USE honghu }
    cse0 = 1 ./ (2.0709734999999e-16 * nden[0+1] + 2.0709734999999e-16 * nden[1+1] + 2.0709734999999e-16 * nden[2+1])
    cse1 = 1 ./ tgas
    cse2 = exp(-157896.75724967 * cse1)
    cse3 = cse2 .* nden[2+1]
    cse4 = cse3 .* nden[0+1] ./ tgas .^ (3 // 2)
    cse5 = sqrt(tgas)
    cse6 = 1 ./ cse5
    cse7 = cse3 .* cse6 .* nden[0+1]
    cse8 = 9.22117062338074e-6 * cse4 + 2.92e-11 * cse7 + 1.16159247118804e-10 * tgas .^ (-1.7) .* nden[1+1] .* nden[2+1]
    cse9 = -cse0 .* cse8
    cse10 = 2.0709734999999e-16 * tgas
    cse11 = cse10 .* cse9
    cse12 = 1.63000002608529e-18 * c_hat
    cse13 = cse12 .* photden[0+1]
    cse14 = cse2 .* cse5
    cse15 = 5.84e-11 * cse14
    cse16 = cse13 + cse15 .* nden[2+1]
    cse17 = 1.65941781598291e-10 * tgas .^ (-0.7)
    cse18 = cse17 .* nden[2+1]
    cse19 = cse17 .* nden[1+1]
    cse20 = cse15 .* nden[0+1]
    cse21 = cse12 .* nden[0+1]
    cse22 = -cse21
    cse23 = cse0 .* cse8
    cse24 = cse10 .* cse23
    cse25 = cse16 - cse24
    cse26 = -cse18 - cse24
    cse27 = -cse19 + cse20 - cse24
    cse28 = 1.27251276978816e-21 * cse14
    cse29 = exp(-118348.0 * cse1)
    cse30 = cse29 .* nden[2+1]
    cse31 = 0.00316227766016838 * cse5 + 1
    cse32 = 1 ./ cse31
    cse33 = 7.5e-19 * cse32
    cse34 = tgas < 100.0
    cse35 = cse0 .* (1.18585412256314e-21 * cse29 .* cse6 .* nden[0+1] .* nden[2+1] ./ cse31 .^ 2 - 8.8761e-14 * cse30 .* cse32 .* nden[0+1] ./ tgas .^ 2 - 2.00925639908347e-16 * cse4 - 6.3625638489408e-22 * cse7 + nden[1+1] .* nden[2+1] .* (-9.2755e-28 * cse6 - ((cse34) ? (0) : (9.26415479e-27 * tgas .^ (-0.89)))))
    cse36 = cse10 .* cse35
    cse37 = -1.8551e-27 * cse5 - ((cse34) ? (0.0) : (8.4219589e-26 * tgas .^ 0.11))
    J[1, 1] = -cse11 - cse16
    J[1, 2] = -cse11 + cse18
    J[1, 3] = -cse11 + cse19 - cse20
    J[1, 4] = cse9
    J[1, 5] = cse22
    J[2, 1] = cse25
    J[2, 2] = cse26
    J[2, 3] = cse27
    J[2, 4] = cse23
    J[2, 5] = cse21
    J[3, 1] = cse25
    J[3, 2] = cse26
    J[3, 3] = cse27
    J[3, 4] = cse23
    J[3, 5] = cse21
    J[4, 1] = 4.19153446811725e-29 * c_hat .* photden[0+1] - cse28 .* nden[2+1] - cse30 .* cse33 - cse36
    J[4, 2] = -cse36 + cse37 .* nden[2+1]
    J[4, 3] = -cse28 .* nden[0+1] - cse29 .* cse33 .* nden[0+1] - cse36 + cse37 .* nden[1+1]
    J[4, 4] = cse35
    J[4, 5] = 4.19153446811725e-29 * c_hat .* nden[0+1]
    J[5, 1] = -cse13
    J[5, 5] = cse22
    J[6, 1] = -cse12 .* rflux[0+1]
    J[6, 6] = cse22
    # $$JAFF END
    return nothing
